#!/usr/bin/env node
// Renders every public page of dbaomarhuertasllc.com into the repo root (the deployable sources).
// The editorial system (Concept B): paper, ink and one emerald; Fraunces 600/700 display, Geist text, Geist Mono folio data.
// One masthead, one folio line, one 12-column frame and one colophon on every page. Styles: assets/site.css.
// Content for the document pages (legal, privacy, terms, accessibility, lexicon) lives in src/content/*.json.
// Every page works without JavaScript; JS adds the menu sheet, the plates drawing themselves, the palette and the form sender.
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {dirname,join} from 'node:path';

const ROOT=join(dirname(fileURLToPath(import.meta.url)),'..');
const ORIGIN='https://dbaomarhuertasllc.com';
const EMAIL='omar@dbaomarhuertasllc.com';
const WEB3FORMS_KEY='6ea6366a-77ee-4e88-9767-deb9aabd4d29';
const CITY='Greensboro, North Carolina';
const STUDIO='https://webdesign.dbaomarhuertasllc.com/';
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const json=async n=>JSON.parse(await readFile(join(ROOT,'src/content',n+'.json'),'utf8'));

const NAV=[['/services.html','ServiceNow'],[STUDIO,'Web Design'],['/about.html','About'],['/contact.html','Contact']];
const LAB=[['/operations-platform.html','Obvera','In development','IT operations with a change record behind every action.'],['/#albena','Albena','Coming soon','A private AI assistant for your own hardware.'],['/#agentgate','AgentGate','Research preview','Approval-bound AI agents, measured.']];
const PAL=[['/services.html','ServiceNow services',''],['/industries.html','Industries',''],['/about.html','About, our story',''],['/servicenow-lexicon/','The ServiceNow Lexicon','96 chapters'],['/support.html','Support',''],['/contact.html','Contact',''],['/services.html#cmdb','CMDB and CSDM strategy','service'],['/services.html#itom','ITOM Discovery and Service Mapping','service'],['/services.html#integration','Integrations and Scripted REST APIs','service'],['/services.html#digital','Websites, apps and digital transformation','digital studio'],['/#story','Our story','home'],['/#tribute','Michael Lombardo tribute','home'],['/support.html#support-form','Open a support request','support'],['/security.html','Trust and security',''],['/privacy-policy.html','Privacy policy','legal'],['/terms.html','Terms and conditions','legal'],['/legal.html','Legal notices','legal'],['/accessibility.html','Accessibility statement',''],[STUDIO,'Web Design Studio','webdesign.dbaomarhuertasllc.com'],['/#albena','Albena, in development, coming soon','albena.ai'],['/operations-platform.html','Obvera, in development, coming soon','obvera platform'],['/#agentgate','AgentGate, research preview, coming soon','agentgate'],['https://albena.ai/waitlist','Join the Albena waitlist','albena.ai waitlist early access']];
const li=`<svg class="li-ic" width="14" height="14" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M20.45 20.45h-3.56v-5.57c0-1.33-.02-3.04-1.85-3.04-1.85 0-2.14 1.45-2.14 2.94v5.67H9.34V9h3.42v1.56h.05c.48-.9 1.64-1.85 3.37-1.85 3.6 0 4.27 2.37 4.27 5.46v6.28zM5.34 7.43a2.07 2.07 0 1 1 0-4.13 2.07 2.07 0 0 1 0 4.13zM7.12 20.45H3.56V9h3.56v11.45zM22.22 0H1.77C.79 0 0 .77 0 1.72v20.56C0 23.23.79 24 1.77 24h20.45c.98 0 1.78-.77 1.78-1.72V1.72C24 .77 23.2 0 22.22 0z"/></svg>`;
const stamp=(t='In development',cls='')=>`<span class="stamp${cls?' '+cls:''}">${t}</span>`;
const btn=(h,t,cls='btn')=>`<a class="${cls}" href="${h}">${t}</a>`;
const pic=(slug,alt,sizes='(max-width:760px) 92vw, 560px',opts={})=>`<picture><source type="image/avif" srcset="/assets/work/${slug}-c600.avif 600w, /assets/work/${slug}-c1200.avif 1200w" sizes="${sizes}"><img src="/assets/work/${slug}-c1200.webp" srcset="/assets/work/${slug}-c600.webp 600w, /assets/work/${slug}-c1200.webp 1200w" sizes="${sizes}" width="1200" height="750" alt="${esc(alt)}" loading="${opts.eager?'eager':'lazy'}" decoding="async"${opts.eager?' fetchpriority="high"':''}></picture>`;
const runhead=(l,r)=>`<div class="runhead"><span>${l}</span><span>${r}</span></div>`;
const sec=(id,cls,inner,label)=>`<section id="${id}" class="wrap sec${cls?' '+cls:''}"${label?` aria-labelledby="${label}"`:''}>${inner}</section>`;
const close=(h2,p,label='Start a conversation',href='/contact.html')=>`<section class="wrap close" aria-labelledby="cl-h"><h2 id="cl-h">${h2}</h2><div class="close-r"><p>${p}</p>${btn(href,label)}<a class="more" href="mailto:${EMAIL}">${EMAIL}</a></div></section>`;

// ----- the shell -----
function page({path,title,description,body,script,bodyClass='',ogImage=`${ORIGIN}/assets/knowledge/k_2026_a.jpg`,folio='',hero=false}){
 const url=ORIGIN+path.replace(/index\.html$/,'');
 const schema={"@context":"https://schema.org","@type":"ProfessionalService","name":"Omar Huertas LLC","url":ORIGIN,"email":EMAIL,"description":"Registered ServiceNow Build, Consulting & Implementation Partner: CMDB, ITAM, ITSM, ITOM, integrations, AI and automation, plus websites and custom applications.","founder":{"@type":"Person","name":"Omar Huertas"},"address":{"@type":"PostalAddress","addressLocality":"Greensboro","addressRegion":"NC","addressCountry":"US"},"sameAs":["https://www.linkedin.com/company/omar-huertas-llc","https://www.linkedin.com/in/omarhuertas"]};
 return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#f2eadb">
<title>${esc(title)}</title>
<meta name="description" content="${esc(description)}">
<link rel="canonical" href="${url}">
<meta property="og:type" content="website">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(description)}">
<meta property="og:url" content="${url}">
<meta property="og:image" content="${ogImage}">
<meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="/assets/favicon.svg" type="image/svg+xml">
<link rel="preload" href="/assets/fonts/fraunces-700-latin.woff2" as="font" type="font/woff2" crossorigin>
<link rel="preload" href="/assets/fonts/Geist-latin.woff2" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="/assets/fonts/fonts.css">
<link rel="stylesheet" href="/assets/site.css">
<script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script>
<script>document.documentElement.classList.add('js')</script>
<script type="module" src="/assets/rt.js"></script>
<script src="/assets/app.js" defer></script>${script?`\n<script type="module" src="/assets/${script}.js"></script>`:''}
</head>
<body${bodyClass?` class="${bodyClass}"`:''}>
<a class="skip" href="#main">Skip to content</a>
${hero?'<div class="wrap hero">':''}${header(path,folio)}${hero?`<main id="main" class="hero-main">${body.hero}</main>${body.strip}</div>${body.rest}`:`<main id="main">
${body}
</main>`}
${footer(path)}
${cmd()}
</body>
</html>
`;
}

// ----- masthead: brand, nav, the lab menu, the call; a thick rule; the folio line; a thin rule -----
function header(path,folio){
 const cur=h=>path===h?' aria-current="page"':'';
 const labMenu=`<div class="navmenu"><a href="/#also" class="navmenu-t">From the lab</a><div class="navpanel"><p class="panel-t">Three projects, none released</p>${LAB.map(([h,t,s,d])=>`<a href="${h}"><b>${t}</b>${stamp(s)}<span>${d}</span></a>`).join('')}</div></div>`;
 return `<header class="hdr" data-hdr>${path==='/index.html'?'':'<div class="wrap">'}<div class="mast"><a class="brand" href="/" aria-label="Omar Huertas LLC, home">Omar Huertas LLC</a>
<nav aria-label="Main" class="hdr-nav">${NAV.map(([h,t])=>`<a href="${h}"${cur(h)}>${t}</a>`).join('')}${labMenu}<a class="cta" href="/contact.html">Start a conversation</a></nav>
<button type="button" class="burger" data-sheet-open aria-expanded="false" aria-controls="sheet"><span class="sr">Menu</span><i aria-hidden="true"></i><i aria-hidden="true"></i></button></div>
<div class="rule thick"></div>
<div class="folio"><span class="sc">Registered ServiceNow Build &amp; Consulting Partner</span>${folio?`<span class="mono">${folio}</span>`:''}<span class="sc">${CITY}</span></div>
<div class="rule r2"></div>${path==='/index.html'?'':'</div>'}</header>
<div id="sheet" class="sheet" data-sheet hidden><div class="sheet-in"><div class="sheet-top"><a class="brand" href="/">Omar Huertas LLC</a><button type="button" class="sheet-x" data-sheet-close><span class="sr">Close menu</span><i aria-hidden="true"></i><i aria-hidden="true"></i></button></div>
<nav class="sheet-nav" aria-label="Menu">${NAV.map(([h,t])=>`<a href="${h}">${t}</a>`).join('')}</nav>
<div class="sheet-lab"><p class="sheet-l">From the lab</p>${LAB.map(([h,t,s])=>`<a href="${h}">${t} ${stamp(s)}</a>`).join('')}</div>
<div class="sheet-foot">${btn('/contact.html','Start a conversation')}<a href="mailto:${EMAIL}">${EMAIL}</a></div></div></div>`;
}

// ----- colophon: the family bar, then contact, partner line and legal -----
function footer(path){
 return `<footer class="foot"><div class="foot-in">
<p class="family"><span class="fam-t">A company of Omar Huertas LLC</span><a href="/"${path==='/index.html'?' aria-current="page"':''}>dbaomarhuertasllc.com</a><a href="https://albena.ai/">albena.ai</a><a href="${STUDIO}">Web Design Studio</a></p>
<div class="foot-grid"><div class="foot-co"><p>A Registered ServiceNow Build, Consulting &amp; Implementation Partner, led by a former architect from top-tier ServiceNow partners. Honest, best-in-class delivery across CMDB, ITAM, ITSM, Integrations, AI, Flow, and Source-to-Pay.</p><p>Registered ServiceNow&reg; Build, Consulting &amp; Implementation Partner.</p></div>
<nav aria-label="Contact"><h2>Contact</h2><a href="mailto:${EMAIL}">${EMAIL}</a><a href="/contact.html">Start a conversation</a><a href="/support.html">Support for clients</a><a href="https://www.linkedin.com/company/omar-huertas-llc" target="_blank" rel="noopener">${li} LinkedIn, company</a><a href="https://www.linkedin.com/in/omarhuertas" target="_blank" rel="noopener">${li} LinkedIn, Omar</a></nav>
<nav aria-label="In this issue"><h2>In this issue</h2><a href="/services.html">ServiceNow services</a><a href="/industries.html">Industries</a><a href="/about.html">Our story</a><a href="/servicenow-lexicon/">The ServiceNow Lexicon</a><a href="/operations-platform.html">Obvera, in development</a><a href="/#albena">Albena, in development</a><a href="/#agentgate">AgentGate, research preview</a><a href="https://albena.ai/waitlist">Join the Albena waitlist</a></nav>
<nav aria-label="Legal"><h2>Legal</h2><a href="/security.html">Trust &amp; security</a><a href="/privacy-policy.html">Privacy policy</a><a href="/terms.html">Terms &amp; conditions</a><a href="/legal.html">Legal notices</a><a href="/accessibility.html">Accessibility</a><a href="/sitemap.xml">Sitemap</a></nav></div>
<div class="foot-bottom"><p class="legacy">&#9826; In honor of <strong>Michael Lombardo</strong>, the Mayor of ServiceNow (1987&ndash;2024). Everything we build is for his legacy. <a href="https://www.joeandruzzifoundation.org" target="_blank" rel="noopener">#LombardoLegacy</a></p><span>&copy; <span data-year>${new Date().getFullYear()}</span> Omar Huertas LLC. All rights reserved.</span><span>${CITY}</span><span>Set in Fraunces and Geist. No trackers.</span></div>
<p class="foot-dis">ServiceNow and the ServiceNow logo are registered trademarks of ServiceNow, Inc. Omar Huertas LLC is an independent ServiceNow partner and is not affiliated with or endorsed by ServiceNow, Inc.</p></div></footer>`;
}

let LEX_PAL=[];
function cmd(){
 const items=[['/','Home',''],...PAL,...LEX_PAL];
 return `<div id="cmd" popover data-island="palette" data-lazy="never"><div class="cmd-in"><div class="cmd-box"><label><span>Go to</span><input type="search" placeholder="Search pages, services, lexicon chapters" autocomplete="off" aria-label="Search pages and lexicon chapters"></label><ul role="list">${items.map(([h,t,m])=>`<li data-k="${esc((t+' '+m).toLowerCase())}"><a href="${h}">${esc(t)}<small>${esc(m)}</small></a></li>`).join('')}</ul><p class="cmd-empty" hidden>Nothing matches. Try a page name, a service or a ServiceNow term.</p><div class="cmd-foot"><span><kbd>↑</kbd> <kbd>↓</kbd> move</span><span><kbd>↵</kbd> open</span><span><kbd>esc</kbd> close</span></div></div></div></div>`;
}

const form=(opts={})=>`<form class="inquiry" data-contact-form action="https://api.web3forms.com/submit" method="post"><input type="hidden" name="access_key" value="${WEB3FORMS_KEY}">${opts.subject?`<input type="hidden" name="subject" value="${esc(opts.subject)}">`:''}<input type="hidden" name="redirect" value="${ORIGIN}${opts.redirect||'/contact.html'}?sent=1"><div class="honeypot" aria-hidden="true"><input type="checkbox" name="botcheck" tabindex="-1" autocomplete="off"></div>
<div class="f-row"><label>Name<input name="name" autocomplete="name" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label></div>
<label>${opts.org||'Company'}<input name="company" autocomplete="organization"></label>
${opts.priority?`<label>Priority <small>(optional)</small><select name="priority"><option value="">Choose one</option><option>General question</option><option>Active project / client</option><option>Urgent / production-down</option></select></label>`:''}
<label>${opts.msgLabel||'What do you need help with?'}<textarea name="message" rows="6" required placeholder="${esc(opts.placeholder||'Tell me what you need help with')}"></textarea></label>
<div class="form-actions"><button type="submit" class="btn">${opts.submit||'Send message'}</button><p class="form-note">${opts.note||'Your message sends straight to our inbox. We reply fast.'}</p></div>
<p class="form-status" role="status" aria-live="polite"></p></form>`;

// ----- Plate I: a service map, engraved (fine lines, hatching, emerald for the CMDB relationships) -----
function PLATE1({id,hero=false}){
 const hatch=`hatch-${id}`,hatch2=`hatch2-${id}`;
 const box=(x,y,label)=>`<g><rect class="dr d1" pathLength="1" x="${x}" y="160" width="140" height="70" fill="url(#${hatch})"/><rect x="${x+6}" y="166" width="128" height="58" fill="#f2eadb" stroke="none"/><rect class="dr d1" pathLength="1" x="${x+6}" y="166" width="128" height="58"/><g class="tx" stroke="none" fill="#121512"><text x="${x+70}" y="192" font-size="14" font-weight="600">Application</text><text x="${x+70}" y="209" font-size="14" font-weight="600">service</text></g></g>`;
 const co=(cx,cy,n)=>`<g class="tx co" stroke="none"><circle cx="${cx}" cy="${cy}" r="11" fill="#0b6b4f"/><text x="${cx}" y="${cy+4.5}" text-anchor="middle" font-family="Fraunces,serif" font-weight="700" font-size="13" fill="#f2eadb">${n}</text></g>`;
 return `<figure class="plate${hero?' hero-plate':''}" id="${id}" data-plate>
<svg viewBox="0 ${hero?30:36} 600 ${hero?430:424}" role="img" aria-labelledby="${id}-t ${id}-d" fill="none" stroke="#121512" stroke-width="1.3" stroke-linecap="round">
<title id="${id}-t">Service map</title><desc id="${id}-d">A business service depends on three application services, which run on servers, a database, a network and a cloud service. Relationships between them are recorded in the CMDB.</desc>
<defs><pattern id="${hatch}" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="5" stroke="#121512" stroke-width=".5" opacity=".45"/></pattern><pattern id="${hatch2}" width="4" height="4" patternUnits="userSpaceOnUse" patternTransform="rotate(-45)"><line x1="0" y1="0" x2="0" y2="4" stroke="#0b6b4f" stroke-width=".5" opacity=".6"/></pattern></defs>
<g stroke="#0b6b4f" stroke-width="${hero?2.4:2}"><path class="dr e1" pathLength="1" d="M300 108 V132 M100 132 H500 M100 132 V160 M300 132 V160 M500 132 V160"/><path class="dr e2" pathLength="1" d="M100 230 V250 M60 250 H220 M60 250 V290 M220 250 V290"/><path class="dr e2" pathLength="1" d="M300 230 V268 M220 268 H380 M220 268 V290 M380 268 V290"/><path class="dr e3" pathLength="1" d="M500 230 V250 M380 250 H540 M380 250 V290 M540 250 V290"/></g>
<g><rect class="dr" pathLength="1" x="190" y="50" width="220" height="58" fill="url(#${hatch2})"/><rect class="dr" pathLength="1" x="196" y="56" width="208" height="46" fill="#f2eadb"/><g class="tx" font-family="Geist,sans-serif" text-anchor="middle" fill="#121512" stroke="none"><text x="300" y="75" font-size="15" font-weight="600">Business service</text><text class="sm" x="300" y="92" font-size="12" fill="#4a4c44">What the customer feels</text></g></g>
<g font-family="Geist,sans-serif" text-anchor="middle">${box(30)}${box(230)}${box(430)}</g>
<g font-family="Geist,sans-serif" text-anchor="middle"><rect class="dr d2" pathLength="1" x="10" y="290" width="100" height="62"/><path class="dr d2" pathLength="1" d="M22 305 H98 M22 316 H98 M22 327 H98 M22 338 H60"/><rect class="dr d2" pathLength="1" x="170" y="290" width="100" height="62"/><path class="dr d2" pathLength="1" d="M182 305 H258 M182 316 H258 M182 327 H258 M182 338 H220"/><path class="dr d3" pathLength="1" d="M330 300 q50 -14 100 0 v38 q-50 14 -100 0z"/><path class="dr d3" pathLength="1" d="M330 316 q50 14 100 0 M330 328 q50 14 100 0"/><rect class="dr d3" pathLength="1" x="490" y="290" width="100" height="62"/><path class="dr d3" pathLength="1" d="M508 336 a14 14 0 0 1 4 -24 a18 18 0 0 1 34 -4 a14 14 0 0 1 24 12 a10 10 0 0 1 0 16z"/><g class="tx" stroke="none" fill="#121512" font-size="13.5" font-weight="500"><text x="60" y="374">Server</text><text x="220" y="374">Server</text><text x="380" y="374">Database</text><text x="540" y="374">Cloud</text></g></g>
<path class="dr d3" pathLength="1" d="M10 420 H590 M10 414 V426 M590 414 V426" stroke-width="1.6"/><path class="tx" d="M60 384 V420 M220 384 V420 M380 384 V420 M540 384 V420" stroke-width="1" stroke-dasharray="3 4"/>
<g class="tx" font-family="Geist,sans-serif" font-size="13.5" font-weight="500" text-anchor="middle" fill="#121512" stroke="none"><text x="300" y="448">Network</text></g>
<g class="tx${hero?' sm':''}" font-family="Geist,sans-serif" font-size="12.5" fill="#0b6b4f" stroke="none" font-weight="600"><text x="316" y="124">CMDB relationships</text></g>
${hero?co(186,150,'01')+co(300,285,'02')+co(522,446,'03')+co(486,368,'04'):''}</svg>
${hero?`<figcaption><span class="t">Plate I. A service map, engraved: what depends on what.</span><ol class="key"><li><b>01</b> Scoped applications</li><li><b>02</b> CMDB &amp; discovery</li><li><b>03</b> ITSM &amp; ITOM</li><li><b>04</b> Integrations &amp; implementation</li></ol></figcaption>`:`<figcaption><span class="t">A service map, from the top down.</span><span><i class="box"></i>Configuration item</span><span><i class="em"></i>CMDB relationship</span><span><i></i>Physical or logical link</span></figcaption>`}
</figure>`;
}
// ----- Plate II: a change, from request to audit (Obvera) -----
const PLATE2=(id='plate2')=>`<figure class="plate" id="${id}" data-plate><svg viewBox="0 0 600 150" role="img" aria-labelledby="${id}-t ${id}-d" fill="none" stroke="#121512" stroke-width="1.3" stroke-linecap="round"><title id="${id}-t">A change moving through Obvera</title><desc id="${id}-d">One rail with four stations: request, approve, execute, audit. The approval is a person.</desc>
<path class="dr e1" pathLength="1" d="M20 70 H580" stroke="#0b6b4f" stroke-width="2.4"/>
<g class="dr d1" pathLength="1"><rect x="40" y="46" width="48" height="48" fill="#f2eadb"/><path d="M52 60 H76 M52 70 H76 M52 80 H66"/></g>
<g class="dr d2" pathLength="1"><circle cx="220" cy="70" r="24" fill="#f2eadb"/><circle cx="220" cy="62" r="7"/><path d="M206 86 a14 14 0 0 1 28 0"/></g>
<g class="dr d2" pathLength="1"><rect x="356" y="46" width="48" height="48" fill="#f2eadb"/><path d="M372 60 l16 10 l-16 10z" fill="#0b6b4f" stroke="#0b6b4f"/></g>
<g class="dr d3" pathLength="1"><rect x="512" y="46" width="48" height="48" fill="#f2eadb"/><path d="M524 72 l8 8 l16 -18"/></g>
<g class="tx" font-family="Geist,sans-serif" font-size="13.5" font-weight="500" text-anchor="middle" fill="#121512" stroke="none"><text x="64" y="122">Request</text><text x="220" y="122">Approve</text><text x="380" y="122">Execute</text><text x="536" y="122">Audit</text></g>
<g class="tx" font-family="Geist,sans-serif" font-size="12" fill="#4a4c44" stroke="none" text-anchor="middle"><text x="64" y="140">risk and rollback</text><text x="220" y="140">a person says yes</text><text x="380" y="140">once, as approved</text><text x="536" y="140">recorded, closed</text></g>
</svg><figcaption><span class="t">Plate II. A change, from request to audit.</span><span><i class="em"></i>The record</span><span><i class="box"></i>A station</span></figcaption></figure>`;
// ----- Plate III: the 404 -----
const PLATE404=`<figure class="plate" id="plate404" data-plate><svg viewBox="0 0 600 420" role="img" aria-labelledby="p4-t" fill="none" stroke="#121512" stroke-width="1.3" stroke-linecap="round"><title id="p4-t">An empty engraved frame</title>
<defs><pattern id="h404" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="5" stroke="#121512" stroke-width=".5" opacity=".45"/></pattern></defs>
<rect class="dr d1" pathLength="1" x="20" y="20" width="560" height="380" fill="url(#h404)"/><rect x="34" y="34" width="532" height="352" fill="#f2eadb" stroke="none"/><rect class="dr d1" pathLength="1" x="34" y="34" width="532" height="352"/>
<path class="dr d2" pathLength="1" d="M60 330 H540" stroke="#0b6b4f" stroke-width="2.4"/><path class="tx" d="M120 300 V330 M300 300 V330 M480 300 V330" stroke-dasharray="3 4"/>
<g class="tx" stroke="none" fill="#121512" font-family="Fraunces,serif" font-weight="700" font-size="190" text-anchor="middle"><text x="300" y="250" letter-spacing="-10">404</text></g>
<g class="tx" font-family="Geist,sans-serif" font-size="13.5" font-weight="500" text-anchor="middle" fill="#121512" stroke="none"><text x="120" y="360">Moved</text><text x="300" y="360">Mistyped</text><text x="480" y="360">Never printed</text></g>
</svg><figcaption><span class="t">Plate 404. A page that is not in this issue.</span></figcaption></figure>`;

// ----- shared content -----
const STORY_BODY=`<p>I was born into technology. I built my first computer at seven, while my stepfather worked for Wang, Northern Telecom, and Oxford. Growing up Puerto Rican on Long Island, I learned early what it means to be underestimated. The aptitude was always there; the world just needed convincing.</p>
<p>So I set out to prove it. At 31 I went back to school and earned an Associate of Applied Science in Network Technology, then stacked the certifications to back it: Cisco CCNA, CompTIA A+, Lean Six Sigma, ServiceNow, and Microsoft. Not because the work needed them, but because the world asked for proof.</p>
<p>A few people saw it before the paper did: <strong>Deena</strong>, <strong>Brian</strong>, and many others who bet on me early. Deena believed in me long before I had any proof. Brian gave me my first real opportunity. <strong>Mike Lombardo</strong>, the Mayor of ServiceNow, showed me the standard, and the GlideFast community he built showed me what it means to treat people right. I&rsquo;ve carried that into every engagement since, delivering on billion-dollar enterprise platforms.</p>
<p>Now I&rsquo;ve started my own: Omar Huertas LLC. Not for the biggest logo in the room, but for honest work, done right, for the people and teams the industry overlooks. <strong>Skill first. Honest work always.</strong></p>`;
